sam (sdk): TS sample (uses async iterator + retry/backoff helper):

```ts
// paginate-retry.ts
import Redwood from '@redwood/inference'
const client = new Redwood()

async function* paginateWithRetry(prompt: string) {
  for await (const resp of client.streamResponses({ model: 'open-3', input: prompt })) {
    try {
      for await (const page of resp.paginate()) {
        yield page
      }
    } catch (e) {
      // backoff then requery cursor
      await sleep(300)
      const newCursor = await client.getCursor(resp.requestId)
      for await (const page of client.fetchPage(newCursor)) {
        yield page
      }
    }
  }
}
```

liam (eng): FYI the Go API uses slightly different naming and doesn't expose fetchPage; we should show the recommended pattern (call ResumeStream with cursor).

sam (sdk): good catch. Go sample:

```go
// paginate_retry.go
package examples

import (
  "context"
  rw "github.com/redwood-inference/go-sdk"
)

func PaginateWithRetry(ctx context.Context, prompt string) chan rw.Page {
  out := make(chan rw.Page)
  go func() {
    defer close(out)
    client := rw.NewClient()
    stream, _ := client.StreamResponses(ctx, rw.StreamOpts{Model: "open-3", Input: prompt})
    for stream.Next() {
      pages, err := stream.Pages()
      if err != nil {
        // transient: obtain latest cursor and resume
        cursor, _ := client.GetCursor(ctx, stream.RequestID())
        resumed := client.ResumeStream(ctx, cursor)
        for resumed.Next() {
          for _, p := range resumed.Pages() {
            out <- p
          }
        }
        return
      }
      for _, p := range pages {
        out <- p
      }
    }
  }()
  return out
}
```

